INSERT INTO file_touch (kind, session_id, path, edit_count, read_count, first_ts, last_ts) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7) ON CONFLICT(kind, session_id, path) DO UPDATE SET edit_count = file_touch.edit_count + excluded.edit_count, read_count = file_touch.read_count + excluded.read_count, first_ts = MIN(COALESCE(file_touch.first_ts, excluded.first_ts), COALESCE(excluded.first_ts, file_touch.first_ts)), last_ts = MAX(COALESCE(file_touch.last_ts, excluded.last_ts), COALESCE(excluded.last_ts, file_touch.last_ts))